$collectInitial = @'
const fs=require('fs'),path=require('path'),zlib=require('zlib');const root=JSON.parse(fs.readFileSync('.dip-local/production-frozen-location.json')).root;
for(const name of fs.readdirSync(path.join(root,'docs/benchmarks')).filter(x=>x.startsWith('2026-10-09-production-')&&x.endsWith('.json')))fs.copyFileSync(path.join(root,'docs/benchmarks',name),path.join('docs/benchmarks',name));
for(const [source,target]of [['.dip-local/production-agent-preflight.json','2026-10-09-production-preflight-v1.json.gz'],[path.join(root,'.dip-local/production-agent-preflight.json'),'2026-10-09-production-preflight-v2.json.gz'],[path.join(root,'.dip-local/production-agent-preflight-v3.json'),'2026-10-09-production-preflight-v3.json.gz']])fs.writeFileSync(path.join('docs/benchmarks',target),zlib.gzipSync(fs.readFileSync(source)));
'@
node -e $collectInitial
